mapper.update:
UPDATE t_user_domain_grant_state
SET granted = #{granted}, revision = #{revision}, updated_at = now()
WHERE user_id = #{userId} AND domain_id = #{domainId}

mapper.select:
SELECT EXISTS(
           SELECT 1
           FROM t_user_role user_role
           JOIN t_role_domain role_domain ON role_domain.role_id = user_role.role_id
           WHERE user_role.user_id = #{userId} AND role_domain.domain_id = #{domainId}
       ) OR EXISTS(
           SELECT 1
           FROM t_user_role user_role
           JOIN t_role_domain_group role_domain_group ON role_domain_group.role_id = user_role.role_id
           JOIN t_domain_group_domain dgd ON dgd.domain_group_id = role_domain_group.domain_group_id
           WHERE user_role.user_id = #{userId} AND dgd.domain_id = #{domainId}
       ) OR EXISTS(
           SELECT 1
           FROM t_user_domain user_domain
           WHERE user_domain.user_id = #{userId} AND user_domain.domain_id = #{domainId}
       ) OR EXISTS(
           SELECT 1
           FROM t_user_domain_group user_domain_group
           JOIN t_domain_group_domain dgd ON dgd.domain_group_id = user_domain_group.domain_group_id
           WHERE user_domain_group.user_id = #{userId} AND dgd.domain_id = #{domainId}
       ) AS granted
